/**
 * VERITAS JURISDICTION CLOCK RESTRAINT RULE (June 2026)
 *
 * All user-facing statutory deadlines MUST be sourced from this file.
 * No deadline number may be generated by model inference at runtime.
 *
 * To add a new entry: verify the day-count directly against current statute text.
 * Do not pattern-match from similar jurisdictions or estimate from training data.
 */

export interface JurisdictionClock {
  statute: string;
  responseDays: number;
  responseUnit: 'business_days' | 'calendar_days';
  extensionDays?: number;
  extensionCondition?: string;
  notes?: string;
}

