// ─── Formatting helper ────────────────────────────────────────────────────────

export function formatDeadline(
  clock: JurisdictionClock & { label?: string }
): string {
  const unit =
    clock.responseUnit === 'business_days' ? 'business days' : 'calendar days';
  let text = `${clock.responseDays} ${unit} (${clock.statute})`;
  if (clock.extensionDays) {
    text += `, extendable by up to ${clock.extensionDays} additional ${unit}`;
    if (clock.extensionCondition) {
      text += ` — ${clock.extensionCondition}`;
    }
  }
  return text;
}
